 * 
 * If you were only permitted to complete at most one transaction (i.e., buy one and sell one share of 
 * the stock), design an algorithm to find the maximum profit.
 * 
 * Note that you cannot sell a stock before you buy one.
 * 
 * Example 1:
 * 
 * Input: [7,1,5,3,6,4]
 * Output: 5
 * Explanation: Buy on day 2 (price = 1) and sell on day 5 (price = 6), profit = 6-1 = 5.
 *              Not 7-1 = 6, as selling price needs to be larger than buying price.
 * 
 * Example 2:
 * 
 * Input: [7,6,4,3,1]
 * Output: 0
 * Explanation: In this case, no transaction is done, i.e. max profit = 0.
 * 
 ******************************************************************************************************/

class Solution {
    public int maxProfit(int[] prices) {
        if (prices == null || prices.length <= 1) {
            return 0;
        }

        var prefixMinSum = prices[0];
        var max = 0;
        for (var i = 1; i < prices.length; i++) {
            max = Math.max(max, prices[i] - prefixMinSum);
            prefixMinSum = Math.min(prefixMinSum, prices[i]);
        }

        return max;
    }

    public int maxProfit_2(int[] prices) {
        if (prices == null || prices.length <= 1) {
            return 0;
        }

        var minSum = prices[0];
        var max = 0;
        for (var i = 1; i < prices.length; i++) {
            max = Math.max(max, prices[i] - minSum);
            minSum = Math.min(minSum, prices[i]);
        }

        return max;
    }
}

